const scrollDotsEl=document.getElementById("scrollDots");const scrollEnergy=document.getElementById("scrollEnergy");const sectionCounter=document.getElementById("sectionCounter");const sectionLabels=["ORIGIN",...drinks.map((d)=>d.name.toUpperCase()),"OVERVIEW","FINALE"];const fsToggleEl=document.getElementById("fsToggle");sections.forEach((s,i)=>{const node=document.createElement("div");node.className="scroll-node";const shape=document.createElement("div");shape.className="scroll-node-shape";shape.innerHTML='<svg viewBox="0 0 28 28" xmlns="http://www.w3.org/2000/svg"><path class="crystal-main" d="M14 2 L24 14 L14 26 L4 14 Z"/><path class="crystal-hi" d="M14 2 L24 14 L14 13 Z"/><path class="crystal-sh" d="M14 26 L4 14 L14 13 Z"/><line class="crystal-line" x1="14" y1="2" x2="14" y2="26" stroke-width="0.4"/><line class="crystal-line" x1="4" y1="14" x2="24" y2="14" stroke-width="0.3"/></svg>';const ring=document.createElement("div");ring.className="scroll-node-ring";const label=document.createElement("div");label.className="scroll-node-label";label.textContent=sectionLabels[i]||"";const idx=document.createElement("div");idx.className="scroll-node-index";idx.textContent=String(i+1).padStart(2,"0");node.appendChild(ring);node.appendChild(shape);node.appendChild(label);node.appendChild(idx);node.addEventListener("click",()=>{const target=s.scrollStart*(document.body.scrollHeight-window.innerHeight);window.scrollTo({top:target,behavior:"smooth"})});scrollDotsEl.appendChild(node)});if(fsToggleEl)scrollDotsEl.appendChild(fsToggleEl);